
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_p86_ft_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_p86_ft", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.003722505158343e-02, -6.903564395946082e-02, -6.760198887190580e-02, -6.555449784989506e-02, -6.264058646774605e-02, -5.851782110785694e-02, -5.274786732639019e-02, -4.485628727145335e-02, -3.462981623378834e-02, -2.292119597266110e-02, -1.309893557082106e-02, -3.942281317279218e-02, -4.622543000046702e-02, -3.387241253498999e-02, -1.786603165943187e-02, -5.846095484298830e-04, 5.949421594191079e-03, -5.655802282186023e-03, -2.271479760166611e-03, -3.222098122602166e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


